// ═══════════════════════════════════════════════════════════════════════
//  CERCADOR DE POBLACIONS — TOWNS_CAT
// ═══════════════════════════════════════════════════════════════════════

(function() {
    if (typeof TOWNS_CAT === 'undefined' || !TOWNS_CAT.towns) {
        console.warn('[Cercador poblacions] TOWNS_CAT no disponible');
        return;
    }

    function normalitzar(s) {
        return (s || '')
            .toString()
            .normalize('NFD')
            .replace(/[\u0300-\u036f]/g, '')
            .toLowerCase()
            .trim();
    }

    const townsIndex = TOWNS_CAT.towns.map(t => ({
        ...t,
        _nn: normalitzar(t.n)
    }));

    function cercarPoblacions(query, maxResultats) {
        const q = normalitzar(query);
        if (!q) return [];
        const resultats = [];
        for (let i = 0; i < townsIndex.length && resultats.length < maxResultats * 6; i++) {
            if (townsIndex[i]._nn.includes(q)) resultats.push(townsIndex[i]);
        }
        resultats.sort((a, b) => {
            const aStarts = a._nn.startsWith(q) ? 0 : 1;
            const bStarts = b._nn.startsWith(q) ? 0 : 1;
            if (aStarts !== bStarts) return aStarts - bStarts;
            return a.n.length - b.n.length;
        });
        return resultats.slice(0, maxResultats);
    }

    function iconaPerTipus(t) {
        switch (t) {
            case 'cim': return 'fa-mountain';
            case 'ciutat': return 'fa-city';
            case 'vila': return 'fa-building';
            default: return 'fa-map-pin';
        }
    }

    // ─── MARCADOR TEMPORAL DE HOVER AL MAPA ────────────────────────────
    let marcadorHover = null;

    function mostrarMarcadorHover(town) {
        if (typeof map === 'undefined') return;
        amagarMarcadorHover();

        const icona = L.divIcon({
            className: 'town-hover-marker',
            html: `<div class="town-hover-dot"></div>`,
            iconSize: [16, 16],
            iconAnchor: [8, 8]
        });

        marcadorHover = L.marker([town.la, town.lo], {
            icon: icona,
            pane: 'paneGeojson',
            interactive: false
        }).addTo(map);
    }

    function amagarMarcadorHover() {
        if (marcadorHover) {
            map.removeLayer(marcadorHover);
            marcadorHover = null;
        }
    }

    // ─── CREACIÓ DE LA UI (caixa de text a la topnav) ──────────────────
    function crearUICercador() {
        const wrapper = document.createElement('div');
        wrapper.id = 'townSearchWrapper';
        wrapper.style.cssText = `
            position: relative;
            display: inline-flex;
            align-items: center;
            margin-right: 12px;
        `;

        wrapper.innerHTML = `
            <div id="townSearchBox" style="
                display: flex;
                align-items: center;
                background: #142338;
                border: 1px solid #2a4361;
                border-radius: 6px;
                padding: 0 10px;
                height: 32px;
                width: 180px;
                transition: width 0.15s ease;
            ">
                <i class="fas fa-magnifying-glass" style="color:#6fc3ff;font-size:12px;margin-right:7px;"></i>
                <input type="text" id="townSearchInput" placeholder="Cercar població..." autocomplete="off" style="
                    flex: 1;
                    background: transparent;
                    border: none;
                    outline: none;
                    color: #e6edf3;
                    font-size: 13px;
                    font-family: inherit;
                    min-width: 0;
                ">
            </div>
        `;
        return wrapper;
    }

    // ─── CREACIÓ DEL DESPLEGABLE (fora de la topnav, penjant de <body>) ─
    function crearResultatsFlotants() {
        const results = document.createElement('div');
        results.id = 'townSearchResults';
        results.style.cssText = `
            display: none;
            position: fixed;
            width: 260px;
            max-height: 320px;
            overflow-y: auto;
            background: #0b1420;
            border: 1px solid #223247;
            border-radius: 8px;
            box-shadow: 0 12px 30px rgba(0,0,0,0.5);
            z-index: 2147483647;
        `;
        document.body.appendChild(results);
        return results;
    }

    function posicionarResultats(box, results) {
        const rect = box.getBoundingClientRect();
        results.style.top = (rect.bottom + 4) + 'px';
        results.style.left = rect.left + 'px';
    }

    function renderResultats(resultats, container, input) {
        if (resultats.length === 0) {
            container.innerHTML = `<div style="padding:14px;color:#556680;font-size:12px;text-align:center;">Sense resultats</div>`;
            container.style.display = 'block';
            return;
        }

        container.innerHTML = `<div style="padding:4px 0;">` + resultats.map((t, idx) => `
            <div class="town-search-item" data-idx="${idx}" style="
                display: flex;
                align-items: center;
                gap: 10px;
                padding: 9px 14px;
                cursor: pointer;
                border-bottom: ${idx === resultats.length - 1 ? 'none' : '1px solid #16202f'};
                font-size: 13px;
                color: #e6edf3;
                transition: background 0.1s ease;
            ">
                <i class="fas ${iconaPerTipus(t.t)}" style="color:#6fc3ff;font-size:12px;width:14px;text-align:center;flex-shrink:0;"></i>
                <span style="flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${t.n}</span>
                ${t.a ? `<span style="color:#556680;font-size:11px;flex-shrink:0;">${t.a}m</span>` : ''}
            </div>
        `).join('') + `</div>`;

        container.querySelectorAll('.town-search-item').forEach((el, idx) => {
            el.addEventListener('mouseenter', () => {
                el.style.background = '#142338';
                mostrarMarcadorHover(resultats[idx]);
            });
            el.addEventListener('mouseleave', () => {
                el.style.background = 'transparent';
                amagarMarcadorHover();
            });
            el.addEventListener('click', () => {
                seleccionarPoblacio(resultats[idx]);
                container.style.display = 'none';
                input.value = resultats[idx].n;
            });
        });

        container.style.display = 'block';
    }

    function seleccionarPoblacio(town) {
        if (typeof map === 'undefined') {
            console.warn('[Cercador poblacions] mapa no disponible');
            return;
        }

        amagarMarcadorHover();

        const targetZoom = Math.max(map.getZoom(), 11);
        map.flyTo([town.la, town.lo], targetZoom, { duration: 0.8 });

        map.once('moveend', function() {
            const point = map.latLngToContainerPoint([town.la, town.lo]);
            map.fire('click', {
                latlng: L.latLng(town.la, town.lo),
                layerPoint: map.containerPointToLayerPoint(point),
                containerPoint: point
            });
        });
    }

    // ─── INICIALITZACIÓ / INSERCIÓ A LA TOPNAV ─────────────────────────
    function inicialitzar() {
        const btnInici = document.querySelector('.topnav-visor-btn[href="index.html"]');
        if (!btnInici || !btnInici.parentElement) {
            console.warn('[Cercador poblacions] Botó Inici no trobat, reintentant...');
            setTimeout(inicialitzar, 300);
            return;
        }

        const ui = crearUICercador();
        btnInici.insertAdjacentElement('afterend', ui);

        const input = document.getElementById('townSearchInput');
        const box = document.getElementById('townSearchBox');
        const results = crearResultatsFlotants();
        let resultatsActuals = [];

        input.addEventListener('input', function() {
            const q = this.value;
            if (!q || q.length < 2) {
                results.style.display = 'none';
                amagarMarcadorHover();
                return;
            }
            resultatsActuals = cercarPoblacions(q, 15);
            posicionarResultats(box, results);
            renderResultats(resultatsActuals, results, input);
        });

        input.addEventListener('keydown', function(e) {
            if (e.key === 'Enter' && resultatsActuals.length > 0) {
                seleccionarPoblacio(resultatsActuals[0]);
                results.style.display = 'none';
                input.value = resultatsActuals[0].n;
                input.blur();
            }
            if (e.key === 'Escape') {
                results.style.display = 'none';
                amagarMarcadorHover();
                input.blur();
            }
        });

        input.addEventListener('focus', function() {
            if (resultatsActuals.length > 0 && this.value.length >= 2) {
                posicionarResultats(box, results);
                results.style.display = 'block';
            }
        });

        window.addEventListener('resize', function() {
            if (results.style.display === 'block') posicionarResultats(box, results);
        });

        document.addEventListener('click', function(e) {
            if (!ui.contains(e.target) && !results.contains(e.target)) {
                results.style.display = 'none';
                amagarMarcadorHover();
            }
        });

        
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', inicialitzar);
    } else {
        inicialitzar();
    }
})();